<style>
    .rp2{--ink:#17324d;--muted:#71879a;--line:#e2ebf2;background:#f4f8fb;min-height:calc(100vh - 90px);padding:24px;color:var(--ink)}
    .rp2-hero{padding:25px 28px;border-radius:22px;background:linear-gradient(135deg,#173d59,#236f9a);color:#fff;box-shadow:0 15px 32px rgba(20,65,98,.18)}
    .rp2-hero h1{margin:0;color:#fff;font-size:1.55rem;font-weight:800}.rp2-hero p{margin:7px 0 0;color:#dcecf6;line-height:1.55}
    .rp2-card{border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 7px 20px rgba(34,70,96,.05)}
    .rp2-toolbar{padding:17px 20px}.rp2-group{overflow:hidden}.rp2-group-head{padding:15px 20px;background:#f7fafc;border-bottom:1px solid var(--line);color:var(--ink);font-weight:800}
    .rp2-row{padding:14px 20px;border-bottom:1px solid #edf2f6}.rp2-row:last-child{border-bottom:0}.rp2-user{color:#17517b;font-weight:800}.rp2-page{font-weight:700;color:#29465d}.rp2-sub{font-size:.74rem;color:#8194a4;overflow-wrap:anywhere}
    .rp2-actions{display:flex;flex-wrap:wrap;gap:5px}.rp2-action{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:4px 8px;background:#e8f3fa;color:#1b6795;font-size:.68rem;font-weight:800}
    .rp2 .btn{border-radius:10px;font-weight:700}.rp2 .form-control,.rp2 .form-select{border-radius:10px;border-color:#d6e3eb}.rp2 .form-label{font-size:.73rem;text-transform:uppercase;letter-spacing:.04em;color:#587287;font-weight:800}
    .rp2-actions-check{display:flex;flex-wrap:wrap;gap:7px}.rp2-actions-check label{display:inline-flex;align-items:center;gap:6px;border:1px solid #d7e4ec;border-radius:999px;padding:6px 10px;background:#fff;color:#476277;font-size:.72rem;font-weight:700;cursor:pointer;transition:.15s ease}.rp2-actions-check label:has(input:checked){background:#e8f3fa;border-color:#8fc8e5;color:#155c86}.rp2-actions-check input{accent-color:#1769aa}.rp2-empty{text-align:center;padding:40px;color:var(--muted)}
    .rp2 .modal-content{border:0;border-radius:18px;overflow:hidden;box-shadow:0 18px 50px rgba(17,54,79,.2)}.rp2 .modal-header{background:#f6f9fb;border-bottom:1px solid var(--line)}
    .rp2 .modal-dialog.rp2-modal-wide{max-width:min(1100px,calc(100vw - 24px));height:calc(100vh - 24px);margin:12px auto}.rp2 .rp2-modal-wide .modal-content{height:100%;display:flex;flex-direction:column}
    .rp2 .rp2-modal-wide .modal-body{min-height:0;overflow:hidden;display:flex;flex-direction:column;padding:0}.rp2 .rp2-modal-wide .modal-footer{flex:0 0 auto;background:#fff;border-top:1px solid var(--line)}
    .rp2-scope{padding:16px 20px;background:#fff;border-bottom:1px solid var(--line);flex:0 0 auto}.rp2-picker-toolbar{padding:12px 20px;background:#f8fbfd;border-bottom:1px solid var(--line);flex:0 0 auto}
    .rp2-page-list{min-height:0;flex:1 1 auto;overflow-y:auto;overflow-x:hidden;padding:12px 20px 22px;background:#fbfdff;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;scrollbar-color:#b9cfdd #fbfdff}
    .rp2-page-list::-webkit-scrollbar{width:10px}.rp2-page-list::-webkit-scrollbar-thumb{background:#b9cfdd;border:3px solid #fbfdff;border-radius:999px}
    .rp2-page-group{border:1px solid var(--line);border-radius:13px;background:#fff;margin-bottom:10px;overflow:hidden}.rp2-page-group:last-child{margin-bottom:0}.rp2-page-group-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 13px;background:#f1f7fa;border-bottom:1px solid var(--line);position:sticky;top:-12px;z-index:2}.rp2-page-group-title{font-weight:800;color:#24516e}.rp2-page-group-count{font-size:.72rem;color:#6d8797}
    .rp2-page-item{display:flex;align-items:flex-start;gap:10px;padding:11px 13px;border-bottom:1px solid #edf2f6}.rp2-page-item:last-child{border-bottom:0}.rp2-page-item.is-hidden{display:none}.rp2-page-item .form-check-input{margin-top:4px;flex:0 0 auto}.rp2-page-meta{min-width:0;flex:1}.rp2-page-name{font-weight:700;color:#29465d}.rp2-page-link{display:block;color:#8194a4;font-size:.72rem;overflow-wrap:anywhere}.rp2-page-actions{margin-top:7px}.rp2-page-actions .rp2-actions-check{gap:5px}.rp2-page-actions .rp2-actions-check label{padding:4px 8px;font-size:.68rem}
