    @media(max-width:700px){.rp2{padding:10px}.rp2-hero{padding:21px 18px;border-radius:17px}.rp2-hero h1{font-size:1.3rem}.rp2-toolbar,.rp2-row{padding:14px}.rp2-hero .btn{width:100%}.rp2 .modal-dialog.rp2-modal-wide{width:calc(100vw - 12px);max-width:none;height:calc(100vh - 12px);margin:6px auto}.rp2 .rp2-modal-wide .modal-header{padding:14px}.rp2-scope,.rp2-picker-toolbar{padding:12px 14px}.rp2-page-list{padding:10px 12px 18px}.rp2-page-group-head{top:-10px}.rp2-page-item{padding:10px}.rp2-page-actions .rp2-actions-check label{font-size:.65rem}.rp2 .modal-footer{padding:12px 14px}.rp2 .modal-footer .btn{flex:1}.rp2-row .rp2-actions{margin-top:4px}}
</style>
