complete="off"></div></div><div class="col-md-5 d-flex justify-content-md-end gap-2"><span class="rp2-selected-count align-self-center" id="rp2SelectedCount">0 pages selected</span><button type="button" class="btn btn-sm btn-outline-primary" id="rp2SelectVisible">Select visible</button><button type="button" class="btn btn-sm btn-outline-secondary" id="rp2ClearPages">Clear</button></div></div></div><div class="rp2-page-list" id="rp2PageList">@foreach($pageOptions->groupBy('main') as $main=>$items)<section class="rp2-page-group" data-group="{{ strtolower($main) }}"><div class="rp2-page-group-head"><span class="rp2-page-group-title"><i class="fas fa-folder-tree me-2 text-primary"></i>{{ $main ?: 'Uncategorised' }}</span><span class="rp2-page-group-count">{{ $items->count() }} pages</span></div>@foreach($items as $pageItem)<div class="rp2-page-item" data-search="{{ strtolower($main.' '.$pageItem->page.' '.$pageItem->link) }}"><input type="checkbox" name="ids[]" value="{{ $pageItem->id }}" class="form-check-input rp2-page-check" aria-label="Select {{ $pageItem->page }}"><div class="rp2-page-meta"><div class="rp2-page-name">{{ $pageItem->page }}</div><span class="rp2-page-link">{{ $pageItem->link }}</span><input type="hidden" name="action{{ $pageItem->id }}" id="rp2NewAction{{ $pageItem->id }}" value="{{ $pageItem->action ?: 'view' }}"><div class="rp2-page-actions"><div class="rp2-actions-check">@php $selected=array_filter(array_map('trim',explode(',',(string)$pageItem->action))); @endphp @foreach($availableActions as $action)<label><input type="checkbox" class="rp2-create-action" data-field="rp2NewAction{{ $pageItem->id }}" value="{{ $action }}" {{ in_array($action,$selected,true) ? 'checked' : '' }}>{{ ucfirst(str_replace(['_','-'],' ',$action)) }}</label>@endforeach</div></div></div></div>@endforeach</section>@endforeach<div class="rp2-picker-empty" id="rp2PickerEmpty">No pages match your search.</div></div></div><div class="modal-footer"><button type="button" class="b