</div>
<script>
(function(){
    function init(){const root=document.querySelector('.rp2');if(!root)return;
        const editActions=[...root.querySelectorAll('.rp2-edit-action')], editActionField=document.getElementById('rp2EditAction');
        function setEditActions(value){const selected=(value||'view').split(',').map(v=>v.trim().toLowerCase()).filter(Boolean);editActions.forEach(c=>c.checked=selected.includes(c.value.toLowerCase()));editActionField.value=selected.join(',')||'view';}
        editActions.forEach(c=>c.addEventListener('change',()=>{editActionField.value=editActions.filter(x=>x.checked).map(x=>x.value).join(',')||'view';}));
        root.querySelectorAll('.rp2-edit-trigger').forEach(b=>b.addEventListener('click',()=>{document.getElementById('rp2EditId').value=b.dataset.id||'';document.getElementById('rp2EditSubtitle').textContent=(b.dataset.username||'Account')+' · '+(b.dataset.page||'Page');document.getElementById('rp2EditFaculty').value=b.dataset.faculty||'all';document.getElementById('rp2EditLevel').value=b.dataset.level||'all';document.getElementById('rp2EditDepartment').value=b.dataset.department||'';document.getElementById('rp2EditProgram').value=b.dataset.program||'';setEditActions(b.dataset.action||'view');}));
        root.querySelectorAll('.rp2-delete-trigger').forEach(b=>b.addEventListener('click',()=>{document.getElementById('rp2DeleteId').value=b.dataset.id||'';document.getElementById('rp2DeletePage').textContent=b.dataset.page||'this page';document.getElementById('rp2DeleteUser').textContent=b.dataset.username||'this account';}));
        const list=document.getElementById('rp2PageList');if(!list)return;const search=document.getElementById('rp2PageSearch'),empty=document.getElementById('rp2PickerEmpty'),count=document.getElementById('rp2SelectedCount');
        function visible(){return [...list.querySelectorAll('.rp2-page-item')].filter(x=>!x.classList.contains('is-hidden'));}
        function refresh(){const n=list.querySelectorAll('.rp2-page-check:checked').length;count.textContent=n+' page'+(n===1?'':'s')+' selected';list.querySelectorAll('.rp2-page-group').forEach(g=>g.style.display=g.querySelectorAll('.rp2-page-item:not(.is-hidden)').length?'':'none');empty.classList.toggle('is-visible',visible().length===0);}
        search.addEventListener('input',()=>{const term=(search.value||'').trim().toLowerCase();list.querySelectorAll('.rp2-page-item').forEach(i=>i.classList.toggle('is-hidden',!!term&&!i.dataset.search.includes(term)));refresh();});
        document.getElementById('rp2SelectVisible').addEventListener('click',()=>{visible().forEach(i=>{const c=i.querySelector('.rp2-page-check');if(c)c.checked=true;});refresh();});
        document.getElementById('rp2ClearPages').addEventListener('click',()=>{list.querySelectorAll('.rp2-page-check').forEach(c=>c.checked=false);refresh();});list.addEventListener('change',e=>{if(e.target.matches('.rp2-page-check'))refresh();});refresh();
        const createForm=document.getElementById('rp2CreateForm');createForm.addEventListener('submit',function(e){const pages=createForm.querySelectorAll('.rp2-page-check:checked');if(!pages.length){e.preventDefault();alert('Select at least one page before granting access.');return;}createForm.querySelectorAll('.rp2-create-action').forEach(check=>{const field=document.getElementById(check.dataset.field);if(!field)return;const checks=[...createForm.querySelectorAll('.rp2-create-action[data-field="'+check.dataset.field+'"]')];field.value=checks.filter(c=>c.checked).map(c=>c.value).join(',')||'view';});const button=document.getElementById('rp2GrantButton');button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>Saving access…';});
    }
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
</script>
